 hardware=gate();hardware.update(python=sys.executable,python_version=sys.version,torch=torch.__version__,cuda_available=torch.cuda.is_available(),cuda_runtime=torch.version.cuda,CPU=platform.processor(),logical_cpus=psutil.cpu_count(),physical_cpus=psutil.cpu_count(False),backend='CPU',threads=2,compiled_operators_required=False,projected_context_feature_bytes=4096*19*4,projected_working_RAM_GiB=1.5,projected_workspace_GiB=3,projected_checkpoint_bytes=10*500000,projected_prediction_csv_bytes=500000000)
